import { readFileSync, writeFileSync } from 'fs';

const p = 'tools/pcb_templates/export.mjs';
let s = readFileSync(p, 'utf8');
const neu = readFileSync('tools/pcb_templates/_hand_analog_ic.mjs', 'utf8').trimEnd() + '\n\n';

const start = s.indexOf('function handLayoutLabAnalogIc(doc)');
const end = s.indexOf('function handLayoutLabDiscrete(doc)');
if (start < 0 || end < 0) {
  console.error('markers', start, end);
  process.exit(1);
}

// Strip any duplicated doc-comments immediately before the function
let cStart = start;
while (cStart > 0) {
  const prev = s.lastIndexOf('/**', cStart - 1);
  if (prev < 0 || start - prev > 800) break;
  const between = s.slice(prev, start);
  if (!/^\s*\/\*\*[\s\S]*\*\/\s*$/.test(between) && !between.includes('模拟 IC')) break;
  // If it's only comment blocks about analog IC, include them in the replace range
  if (between.includes('模拟 IC') || between.includes('handLayoutLabAnalogIc')) {
    cStart = prev;
  } else break;
  if (cStart === prev) {
    // keep walking back over consecutive analog comments
    const earlier = s.lastIndexOf('/**', cStart - 1);
    if (earlier >= 0 && start - earlier < 2000 && s.slice(earlier, cStart).includes('模拟 IC')) {
      cStart = earlier;
      continue;
    }
    break;
  }
}

s = s.slice(0, cStart) + neu + s.slice(end);

writeFileSync(p, s);
const nFn = (s.match(/function handLayoutLabAnalogIc/g) || []).length;
const nDoc = (s.match(/模拟 IC 检测手布/g) || []).length;
console.log({ nFn, nDoc, hasOrtho: s.includes('正交回焊盘'), hasUpLeft: s.includes('先上再左') });
